"""Render the confirmed bounded handoff; generated by az-01-conductor on 2026-10-23."""

from pathlib import Path

from diagrams import Cluster, Diagram, Edge, Node
from diagrams.azure.ml import CognitiveServices
from diagrams.azure.security import KeyVaults
from diagrams.azure.storage import BlobStorage
from diagrams.onprem.client import Users

OUTPUT = Path(__file__).resolve().with_suffix("")
GRAPH = {
    "bgcolor": "white",
    "fontname": "Arial",
    "fontsize": "22",
    "pad": "0.5",
    "nodesep": "0.9",
    "ranksep": "0.8",
    "splines": "spline",
    "dpi": "150",
    "labelloc": "t",
}
NODES = {"fontname": "Arial", "fontsize": "12", "labelloc": "b"}
EDGES = {"fontname": "Arial", "fontsize": "11", "color": "#2368a0"}
CLUSTER = {"fontname": "Arial", "fontsize": "15", "margin": "24"}


def step(label: str, *, fill: str = "#edf5ff") -> Node:
    """Create a readable application action, not an additional Azure resource."""
    return Node(
        label,
        shape="box",
        style="rounded,filled",
        fillcolor=fill,
        labelloc="c",
        width="4.3",
        height="1.0",
    )


def main() -> None:
    """Write the runtime PNG locally; arrows specify planned behavior, not test results."""
    with Diagram(
        "Adventure Works Cycles | Sales-to-Marketing handoff\n"
        "Confirmed local design - NOT a live execution trace",
        filename=str(OUTPUT),
        show=False,
        direction="TB",
        graph_attr=GRAPH,
        node_attr=NODES,
        edge_attr=EDGES,
    ):
        n_web_browser_request = Users("Synthetic opportunity\nPOST /api/handoffs")
        with Cluster(
            "Reference resource group | logical sequence, not subnet placement\n"
            "Private ACA app controls all three Foundry invocations and every validation gate",
            graph_attr=CLUSTER,
        ) as clu_rg_workload:
            n_edge_apim_admission = step(
                "1. Public APIM\nThrottle + correlation ID\nReplace backend Authorization"
            )
            n_app_auth_admission = step(
                "2. Private ACA: authenticate + admit\nJWT issuer / tenant / audience / gateway ID\n"
                "Known opportunity; input <= 4,000 chars"
            )
            n_app_agent_sales = CognitiveServices(
                "3. Foundry: Sales Fit\nPinned sales-fit version | separate context\n"
                "Read-only opportunity + product tools"
            )
            n_app_sales_projection = step(
                "4. App validates Sales + projects handoff\nTyped fit / unknowns / source IDs only\n"
                "No margin, discount or contact fields"
            )
            n_app_agent_marketing = CognitiveServices(
                "5. Foundry: Marketing Claims\nPinned marketing-claims version | separate context\n"
                "Sanitized Sales handoff; approved-claims tool"
            )
            n_app_marketing_validation = step(
                "6. App validates Marketing\nApproved wording + versioned citations\n"
                "Reject unsupported 200 km guarantee"
            )
            n_app_agent_coordinator = CognitiveServices(
                "7. Foundry: Handoff Coordinator\nPinned handoff-coordinator version | no tools\n"
                "Validated Sales + Marketing structures only"
            )
            n_app_packet_validation = step(
                "8. App validates + deterministically renders\nAllowlisted sources / caveats / provenance\n"
                "Enforce reviewRequired: true"
            )
            n_app_packet_digest = step(
                "9. App canonicalizes UTF-8 packet + SHA-256\nCovers content and full returned provenance\n"
                "Signature envelope excluded"
            )
            n_sec_keyvault_receipt = KeyVaults(
                "10. Private Key Vault: sign digest\nApp MI: key-scoped Crypto User\nRSA-2048 / PS256"
            )
            n_app_signature_response = step(
                "11. App returns packet + integrity envelope\nDigest / signature / key version\n"
                "Actual agent IDs / versions / response IDs"
            )
            n_app_tool_executor = step(
                "App-side read-only tool executor\nSales: get_opportunity / get_product\n"
                "Marketing: get_approved_claims\nValidate arguments + IDs; minimal projections",
                fill="#edf8ee",
            )
            n_data_blob_sources = BlobStorage(
                "Private versioned Blob fixtures\nProducts / opportunities / approved claims\n"
                "App MI: container-scoped Reader"
            )
            n_app_error_response = step(
                "Any stage failure: safe error + correlation\n400 / 404 / 429 / 502 / 503 / 504\n"
                "JWT: 401/403; public backend: unreachable\nNo completed packet or fallback success",
                fill="#fff0ef",
            )
            n_app_runtime_bounds = step(
                "Bounds across the entire handoff\n4 concurrent requests / replica; 90 seconds\n"
                "<= 7 Responses calls, including retries\n800 output tokens / call; 30,000 total tokens",
                fill="#fff8e6",
            )
            n_ops_trace_metadata = step(
                "Redacted Log Analytics telemetry\nEvery stage: correlation / response IDs\n"
                "Duration / usage / safe error code\nNo raw prompts or chain-of-thought",
                fill="#f4f4f4",
            )
            for nodes in (
                (n_app_auth_admission, n_app_runtime_bounds),
                (n_app_agent_sales, n_app_tool_executor),
                (n_app_agent_marketing, n_data_blob_sources),
                (n_app_packet_validation, n_app_error_response),
                (n_app_signature_response, n_ops_trace_metadata),
            ):
                with clu_rg_workload.dot.subgraph() as row:
                    row.attr(rank="same")
                    for node in nodes:
                        row.node(node.nodeid)
        n_web_human_review = Users(
            "Human review required\nDraft only; never publish or order\nSignature proves integrity, not approval"
        )

        n_web_browser_request >> Edge(label="request: HTTPS") >> n_edge_apim_admission
        n_edge_apim_admission >> Edge(label="auth: gateway MI JWT; private backend") >> n_app_auth_admission
        n_app_auth_admission >> Edge(label="request: app MI / private Responses API") >> n_app_agent_sales
        n_app_agent_sales >> Edge(label="response: structured fit + sources") >> n_app_sales_projection
        n_app_sales_projection >> Edge(label="request: app MI / private Responses API") >> n_app_agent_marketing
        n_app_agent_marketing >> Edge(label="response: claims draft + sources") >> n_app_marketing_validation
        n_app_marketing_validation >> Edge(label="request: app MI / private Responses API") >> n_app_agent_coordinator
        n_app_agent_coordinator >> Edge(label="response: review packet") >> n_app_packet_validation
        n_app_packet_validation >> n_app_packet_digest
        n_app_packet_digest >> Edge(label="request: private HTTPS + app MI") >> n_sec_keyvault_receipt
        n_sec_keyvault_receipt >> Edge(label="response: signature + key version") >> n_app_signature_response
        n_app_signature_response >> Edge(label="response: via APIM; same correlation") >> n_web_human_review

        # Tool loops are side paths; rank constraints would obscure the sequential business handoff.
        [n_app_agent_sales, n_app_agent_marketing] >> Edge(
            label="response: function call\nrequest: validated tool output",
            dir="both",
            constraint="false",
        ) >> n_app_tool_executor
        n_app_tool_executor >> Edge(
            label="read: private HTTPS + app MI\nAgents never access Blob directly"
        ) >> n_data_blob_sources
        n_app_runtime_bounds >> Edge(
            label="enforce: all stages", style="dashed", color="#b34135", constraint="false"
        ) >> n_app_auth_admission
        n_app_packet_validation >> Edge(
            label="failure: example gate\nApplies to every dependency / tool / agent / signing step",
            style="dashed",
            color="#b34135",
            constraint="false",
        ) >> n_app_error_response
        n_app_signature_response >> Edge(
            label="telemetry: success AND failure", style="dotted", color="#737373", constraint="false"
        ) >> n_ops_trace_metadata


if __name__ == "__main__":
    main()
